/* =========================================================================
 *  持久化
 *  ========================================================================= */
function loadFromStorage() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return null
    return JSON.parse(raw)
  } catch (e) {
    console.warn('[choicesStore] 加载失败，使用默认值', e)
    return null
  }
}

const ALL_KEYS = [
  'factionLevels', 'characterStatus', 'realmTiers',
  'artifactRarity', 'creatureDanger', 'anomalyDanger',
  'eras', 'relationTypes', 'originLawTiers', 'loreCategories',
  'abilitySystems', 'professions', 'currencies',
]

function saveToStorage(state) {
  try {
    const payload = {}
    ALL_KEYS.forEach((k) => { payload[k] = state[k]?.value ?? state[k] })
    localStorage.setItem(STORAGE_KEY, JSON.stringify(payload))
  } catch (e) {
    console.warn('[choicesStore] 保存失败', e)
  }
}

/* =========================================================================
 *  Store 主体
 *  ========================================================================= */
export const useChoicesStore = defineStore('choices', () => {
  const stored = loadFromStorage()

  // 13 个核心 choices 集合
  const factionLevels   = ref(stored?.factionLevels   ?? [...DEFAULT_FACTION_LEVELS])
  const characterStatus = ref(stored?.characterStatus ?? [...DEFAULT_CHARACTER_STATUS])
  const realmTiers      = ref(stored?.realmTiers      ?? [...DEFAULT_REALM_TIERS])
  const artifactRarity  = ref(stored?.artifactRarity  ?? [...DEFAULT_ARTIFACT_RARITY])
  const creatureDanger  = ref(stored?.creatureDanger  ?? [...DEFAULT_CREATURE_DANGER])
  const anomalyDanger   = ref(stored?.anomalyDanger   ?? [...DEFAULT_ANOMALY_DANGER])
  const eras            = ref(stored?.eras            ?? [...DEFAULT_ERAS])
  const relationTypes   = ref(stored?.relationTypes   ?? [...DEFAULT_RELATION_TYPES])
  const originLawTiers  = ref(stored?.originLawTiers  ?? [...DEFAULT_ORIGIN_LAW_TIERS])
  const loreCategories  = ref(stored?.loreCategories  ?? [...DEFAULT_LORE_CATEGORIES])
  const abilitySystems  = ref(stored?.abilitySystems  ?? [...DEFAULT_ABILITY_SYSTEMS])
  const professions     = ref(stored?.professions     ?? [...DEFAULT_PROFESSIONS])
  const currencies      = ref(stored?.currencies      ?? [...DEFAULT_CURRENCIES])

  /* ===== helpers ===== */
  function sortByWeight(list) {
    return list.value.sort((a, b) => (a.weight || 99) - (b.weight || 99))
  }
  function upsert(list, item) {
    const idx = list.value.findIndex((x) => x.key === item.key)
    if (idx >= 0) list.value[idx] = { ...list.value[idx], ...item }
    else          list.value.push({ weight: 99, ...item })
    sortByWeight(list)
  }
  function remove(list, key) {
    const idx = list.value.findIndex((x) => x.key === key)
    if (idx >= 0) list.value.splice(idx, 1)
  }
  function toOptions(list) {
    return list.value
      .slice()
      .sort((a, b) => (a.weight || 99) - (b.weight || 99))
      .map((x) => ({ value: x.key, label: x.label, color: x.color, desc: x.desc }))
  }
  function findItem(list, key) {
    return list.value.find((x) => x.key === key) || { label: key, color: 'gray' }
  }

  /** 通用：批量替换（套用模板时使用） */
  function replaceAll(list, items) {
    list.value = (items || []).slice()
    sortByWeight(list)
  }

  /* ===== 对外 API =====
   *  为每个集合提供 4 个方法：
   *   - xxxOptions()   → 返回下拉选项
   *   - upsertXxx(item) → 新增或更新一项
   *   - removeXxx(key)  → 按 key 删除
   *   - getXxx(key)     → 按 key 查询
   *   - setXxxAll(arr)  → 整体替换（套用模板）
   */

  // 族群等级
  const factionLevelOptions = () => toOptions(factionLevels)
  function upsertFactionLevel(i) { upsert(factionLevels, i) }
  function removeFactionLevel(k) { remove(factionLevels, k) }
  function getFactionLevel(k)   { return findItem(factionLevels, k) }
  function setFactionLevelsAll(arr) { replaceAll(factionLevels, arr) }

  // 角色状态
  const characterStatusOptions = () => toOptions(characterStatus)
  function upsertCharacterStatus(i) { upsert(characterStatus, i) }
  function removeCharacterStatus(k) { remove(characterStatus, k) }
  function getCharacterStatus(k)   { return findItem(characterStatus, k) }
  function setCharacterStatusAll(arr) { replaceAll(characterStatus, arr) }

  // 境界大阶
  const realmTierOptions = () => toOptions(realmTiers)
  function upsertRealmTier(i) { upsert(realmTiers, i) }
  function removeRealmTier(k) { remove(realmTiers, k) }
  function getRealmTier(k)   { return findItem(realmTiers, k) }
  function setRealmTiersAll(arr) { replaceAll(realmTiers, arr) }

  // 宝物稀有度
  const artifactRarityOptions = () => toOptions(artifactRarity)
  function upsertArtifactRarity(i) { upsert(artifactRarity, i) }
  function removeArtifactRarity(k) { remove(artifactRarity, k) }
  function getArtifactRarity(k)   { return findItem(artifactRarity, k) }
  function setArtifactRarityAll(arr) { replaceAll(artifactRarity, arr) }

  // 异兽危险等级
  const creatureDangerOptions = () => toOptions(creatureDanger)
  function upsertCreatureDanger(i) { upsert(creatureDanger, i) }
  function removeCreatureDanger(k) { remove(creatureDanger, k) }
  function getCreatureDanger(k)   { return findItem(creatureDanger, k) }
  function setCreatureDangerAll(arr) { replaceAll(creatureDanger, arr) }

  // 异常物危险等级
  const anomalyDangerOptions = () => toOptions(anomalyDanger)
  function upsertAnomalyDanger(i) { upsert(anomalyDanger, i) }
  function removeAnomalyDanger(k) { remove(anomalyDanger, k) }
  function getAnomalyDanger(k)   { return findItem(anomalyDanger, k) }
  function setAnomalyDangerAll(arr) { replaceAll(anomalyDanger, arr) }

  // 历史时代
  const eraOptions = () => toOptions(eras)
  function upsertEra(i) { upsert(eras, i) }
  function removeEra(k) { remove(eras, k) }
  function getEra(k)   { return findItem(eras, k) }
  function setErasAll(arr) { replaceAll(eras, arr) }

  // 关系类型
  const relationTypeOptions = () => toOptions(relationTypes)
  function upsertRelationType(i) { upsert(relationTypes, i) }
  function removeRelationType(k) { remove(relationTypes, k) }
  function getRelationType(k)   { return findItem(relationTypes, k) }
  function setRelationTypesAll(arr) { replaceAll(relationTypes, arr) }

  // 本源法则层级
  const originLawTierOptions = () => toOptions(originLawTiers)
  function upsertOriginLawTier(i) { upsert(originLawTiers, i) }
  function removeOriginLawTier(k) { remove(originLawTiers, k) }
  function getOriginLawTier(k)   { return findItem(originLawTiers, k) }
  function setOriginLawTiersAll(arr) { replaceAll(originLawTiers, arr) }

  // 设定页分类
  const loreCategoryOptions = () => toOptions(loreCategories)
  function upsertLoreCategory(i) { upsert(loreCategories, i) }
  function removeLoreCategory(k) { remove(loreCategories, k) }
  function getLoreCategory(k)   { return findItem(loreCategories, k) }
  function setLoreCategoriesAll(arr) { replaceAll(loreCategories, arr) }

  // 能力体系
  const abilitySystemOptions = () => toOptions(abilitySystems)
  function upsertAbilitySystem(i) { upsert(abilitySystems, i) }
  function removeAbilitySystem(k) { remove(abilitySystems, k) }
  function getAbilitySystem(k)   { return findItem(abilitySystems, k) }
  function setAbilitySystemsAll(arr) { replaceAll(abilitySystems, arr) }

  // 职业体系
  const professionOptions = () => toOptions(professions)
  function upsertProfession(i) { upsert(professions, i) }
  function removeProfession(k) { remove(professions, k) }
  function getProfession(k)   { return findItem(professions, k) }
  function setProfessionsAll(arr) { replaceAll(professions, arr) }

  // 货币 / 灵石体系
  const currencyOptions = () => toOptions(currencies)
  function upsertCurrency(i) { upsert(currencies, i) }
  function removeCurrency(k) { remove(currencies, k) }
  function getCurrency(k)   { return findItem(currencies, k) }
  function setCurrenciesAll(arr) { replaceAll(currencies, arr) }

  /* ===== 全量恢复默认 ===== */
  function resetAll() {
    factionLevels.value   = [...DEFAULT_FACTION_LEVELS]
    characterStatus.value = [...DEFAULT_CHARACTER_STATUS]
    realmTiers.value      = [...DEFAULT_REALM_TIERS]
    artifactRarity.value  = [...DEFAULT_ARTIFACT_RARITY]
    creatureDanger.value  = [...DEFAULT_CREATURE_DANGER]
    anomalyDanger.value   = [...DEFAULT_ANOMALY_DANGER]
    eras.value            = [...DEFAULT_ERAS]
    relationTypes.value   = [...DEFAULT_RELATION_TYPES]
    originLawTiers.value  = [...DEFAULT_ORIGIN_LAW_TIERS]
    loreCategories.value  = [...DEFAULT_LORE_CATEGORIES]
    abilitySystems.value  = [...DEFAULT_ABILITY_SYSTEMS]
    professions.value     = [...DEFAULT_PROFESSIONS]
    currencies.value      = [...DEFAULT_CURRENCIES]
  }

  /* ===== 持久化 watch ===== */
  watch(
    [factionLevels, characterStatus, realmTiers, artifactRarity, creatureDanger,
     anomalyDanger, eras, relationTypes, originLawTiers, loreCategories,
     abilitySystems, professions, currencies],
    () => saveToStorage({
      factionLevels: factionLevels.value,
      characterStatus: characterStatus.value,
      realmTiers: realmTiers.value,
      artifactRarity: artifactRarity.value,
      creatureDanger: creatureDanger.value,
      anomalyDanger: anomalyDanger.value,
      eras: eras.value,
      relationTypes: relationTypes.value,
      originLawTiers: originLawTiers.value,
      loreCategories: loreCategories.value,
      abilitySystems: abilitySystems.value,
      professions: professions.value,
      currencies: currencies.value,
    }),
    { deep: true }
  )

  return {
    // state
    factionLevels, characterStatus, realmTiers, artifactRarity, creatureDanger,
    anomalyDanger, eras, relationTypes, originLawTiers, loreCategories,
    abilitySystems, professions, currencies,
    // 通用 getter
    factionLevelOptions, characterStatusOptions, realmTierOptions,
    artifactRarityOptions, creatureDangerOptions, anomalyDangerOptions,
    eraOptions, relationTypeOptions, originLawTierOptions, loreCategoryOptions,
    abilitySystemOptions, professionOptions, currencyOptions,
    // upsert / remove / get
    upsertFactionLevel, removeFactionLevel, getFactionLevel, setFactionLevelsAll,
    upsertCharacterStatus, removeCharacterStatus, getCharacterStatus, setCharacterStatusAll,
    upsertRealmTier, removeRealmTier, getRealmTier, setRealmTiersAll,
    upsertArtifactRarity, removeArtifactRarity, getArtifactRarity, setArtifactRarityAll,
    upsertCreatureDanger, removeCreatureDanger, getCreatureDanger, setCreatureDangerAll,
    upsertAnomalyDanger, removeAnomalyDanger, getAnomalyDanger, setAnomalyDangerAll,
    upsertEra, removeEra, getEra, setErasAll,
    upsertRelationType, removeRelationType, getRelationType, setRelationTypesAll,
    upsertOriginLawTier, removeOriginLawTier, getOriginLawTier, setOriginLawTiersAll,
    upsertLoreCategory, removeLoreCategory, getLoreCategory, setLoreCategoriesAll,
    upsertAbilitySystem, removeAbilitySystem, getAbilitySystem, setAbilitySystemsAll,
    upsertProfession, removeProfession, getProfession, setProfessionsAll,
    upsertCurrency, removeCurrency, getCurrency, setCurrenciesAll,
    // utils
    resetAll,
  }
})
